import datetimeimport tkinter as tkimport shutilimport monitor_cpu"""Faire un exe:pip install pyinstallerpyinstaller --onefile --noconsole monitor_disk.py=> dist/monitor_disk.exe (9Mo)Pour tuer le programme:taskkill /F /IM monitor_disk.exe"""# =========================================================# CONFIGURATION# =========================================================REFRESH_MS = 5000RIGHT_MARGIN = 270TOP_MARGIN = -2# =========================================================# ESPACE DISQUE# =========================================================def get_free_space(drive):    try:        free = shutil.disk_usage(drive).free        return free / (1024 ** 3)    except Exception:        return None        def get_hhmm():    return datetime.datetime.now().strftime("%H:%M")# =========================================================# MISE À JOUR# =========================================================after_id = Nonedef update():    global after_id    c = get_free_space("C:\\")    d = get_free_space("D:\\")    parts = []    if c is not None:        parts.append(f"C: {c:.1f} Go")    else:        parts.append("C: ?")    if d is not None:        parts.append(f"D: {d:.1f} Go")    else:        parts.append("D: ?")            #~ procs = monitor_cpu.get_top_cpu_processes()    load = monitor_cpu.get_cpu_total_usage()    parts.append(f"{load:2.0f} %")        parts.append(get_hhmm())    label.config(        text="    ".join(parts)    )        after_id = root.after(        REFRESH_MS,        update    )    # =========================================================# MENU CONTEXTUEL# =========================================================context_popup = Nonedef close_context_menu():    global context_popup    if context_popup is not None:        try:            context_popup.destroy()        except tk.TclError:            pass        context_popup = Nonedef exit_app():    global after_id    # Ferme le menu    close_context_menu()    # Annule le timer    if after_id is not None:        try:            root.after_cancel(after_id)        except tk.TclError:            pass        after_id = None    # Ferme l'application    root.destroy()def show_context_menu(event):    global context_popup    # Ferme un éventuel menu existant    close_context_menu()    # -----------------------------------------------------    # Création du popup    # -----------------------------------------------------    context_popup = tk.Toplevel(root)    context_popup.overrideredirect(True)    context_popup.attributes(        "-topmost",        True    )    context_popup.configure(        bg="#303030"    )    # -----------------------------------------------------    # Cadre    # -----------------------------------------------------    frame = tk.Frame(        context_popup,        bg="#303030",        bd=1,        relief="solid"    )    frame.pack(        padx=0,        pady=0    )    # -----------------------------------------------------    # Bouton Exit    # -----------------------------------------------------    exit_button = tk.Button(        frame,        text="Exit",        font=("Segoe UI", 9),        fg="white",        bg="#303030",        activeforeground="white",        activebackground="#505050",        relief="flat",        borderwidth=0,        highlightthickness=0,        padx=25,        pady=4,        cursor="arrow",        command=exit_app    )    exit_button.pack()    # -----------------------------------------------------    # Taille    # -----------------------------------------------------    context_popup.update_idletasks()    menu_width = context_popup.winfo_width()    menu_height = context_popup.winfo_height()    # -----------------------------------------------------    # Position souris    # -----------------------------------------------------    x = event.x_root    y = event.y_root    # Évite de sortir de l'écran à droite    screen_width = root.winfo_screenwidth()    if x + menu_width > screen_width:        x = screen_width - menu_width    # Évite de sortir de l'écran en bas    screen_height = root.winfo_screenheight()    if y + menu_height > screen_height:        y = screen_height - menu_height    context_popup.geometry(        f"+{x}+{y}"    )    context_popup.lift()    # Donne immédiatement le focus au bouton    exit_button.focus_set()# =========================================================# DÉPLACEMENT# =========================================================drag_x = 0drag_y = 0def start_move(event):    global drag_x    global drag_y    close_context_menu()    drag_x = event.x    drag_y = event.ydef move_window(event):    x = (        root.winfo_x()        + event.x        - drag_x    )    y = (        root.winfo_y()        + event.y        - drag_y    )    root.geometry(        f"+{x}+{y}"    )# =========================================================# FENÊTRE# =========================================================root = tk.Tk()root.overrideredirect(True)root.attributes(    "-topmost",    True)root.attributes(    "-alpha",    0.80)root.configure(    bg="black")# =========================================================# LABEL# =========================================================label = tk.Label(    root,    text="",    font=("Segoe UI", 8),    fg="white",    bg="gray",    padx=2,    pady=0)label.pack()# =========================================================# CLIC GAUCHE = DÉPLACEMENT# =========================================================root.bind(    "<Button-1>",    start_move)root.bind(    "<B1-Motion>",    move_window)label.bind(    "<Button-1>",    start_move)label.bind(    "<B1-Motion>",    move_window)# =========================================================# CLIC DROIT = MENU# =========================================================root.bind(    "<Button-3>",    show_context_menu)label.bind(    "<Button-3>",    show_context_menu)# =========================================================# CALCUL DE LA TAILLE# =========================================================root.update_idletasks()# =========================================================# POSITION INITIALE HAUT-DROITE# =========================================================screen_width = root.winfo_screenwidth()window_width = root.winfo_width()x = (    screen_width    - window_width    - RIGHT_MARGIN)y = TOP_MARGINroot.geometry(    f"+{x}+{y}")# =========================================================# ARRONDI - DÉSACTIVÉ# ========================================================="""def make_rounded(hwnd, width, height, radius=10):    import ctypes    user32 = ctypes.windll.user32    gdi32 = ctypes.windll.gdi32    region = gdi32.CreateRoundRectRgn(        0,        0,        width,        height,        radius * 2,        radius * 2    )    user32.SetWindowRgn(        hwnd,        region,        True    )root.update_idletasks()make_rounded(    root.winfo_id(),    root.winfo_width(),    root.winfo_height(),    10)"""# =========================================================# DÉMARRAGE# =========================================================update()root.mainloop()